    this.thresholdDb = -55;
    this.attack = 0.002;
    this.release = 0.12;
    this.holdSamples = Math.round(0.06 * sampleRate);
    this.env = 0;
    this.gain = 1;
    this.open = true;
    this.holdCounter = 0;
    this.peakSinceReport = 0;
