    const input = inputs[0];
    const output = outputs[0];
    if (!output || output.length === 0) return true;
    const n = output[0].length;
    const inCh = input && input.length ? input[0] : null;

    const envRel = Math.exp(-1 / (0.05 * sampleRate));
