    this.r = sr / this.D;
    this.dec = new Float32Array(4096);
    this.dw = 0;
    this.acc = 0;
    this.accN = 0;
    this.hop = Math.round(0.008 * this.r);
    this.sinceHop = 0;
    this.W = Math.round(0.02 * this.r);
    this.maxLag = Math.round(this.r / 95);
